async function handleBooking(request,env){
 const headers={'content-type':'application/json;charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff'};
 const reply=(status,message,extra={})=>new Response(JSON.stringify({success:status<300,message,...extra}),{status,headers});
 if(request.method!=='POST')return reply(405,'Méthode non autorisée.');
 const origin=request.headers.get('Origin');let originHost=null;
 try{originHost=origin?new URL(origin).host:null;}catch{return reply(403,'Origine non autorisée.');}
 if(!originHost||originHost!==new URL(request.url).host)return reply(403,'Origine non autorisée.');
 if(!/application\/json/i.test(request.headers.get('Content-Type')||''))return reply(415,'Format de requête invalide.');
 const size=Number(request.headers.get('Content-Length')||0);if(size>12000)return reply(413,'Formulaire trop volumineux.');
 let raw;try{const text=await request.text();if(text.length>12000)return reply(413,'Formulaire trop volumineux.');raw=JSON.parse(text);}catch{return reply(400,'Données incorrectes.');}
 if(!raw||typeof raw!=='object'||Array.isArray(raw))return reply(400,'Données incorrectes.');
 if(raw.website)return reply(400,'Demande invalide.');
 if(typeof raw.started_at!=='number'||Date.now()-raw.started_at<1800||Date.now()-raw.started_at>86400000)return reply(400,'Veuillez réessayer depuis le formulaire.');
 const val=(key,max)=>typeof raw[key]==='string'?raw[key].trim().slice(0,max):'';
 const b={nom:val('nom',80),telephone:val('telephone',30),depart:val('depart',170),destination:val('destination',170),date:val('date',10),heure:val('heure',5),type:val('type',45),email:val('email',120),retour:raw.retour===true,details:val('details',500)};
 if(!b.nom||b.nom.length<2||!/^[+0-9() .-]{8,30}$/.test(b.telephone)||b.depart.length<3||b.destination.length<3||!/^\d{4}-\d{2}-\d{2}$/.test(b.date)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(b.heure))return reply(422,'Merci de vérifier vos coordonnées et votre trajet.');
 if(!['Taxi conventionné CPAM','Taxi classique','Van','Berline prestige'].includes(b.type))return reply(422,'Catégorie de véhicule invalide.');
 if(b.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(b.email))return reply(422,'Adresse email invalide.');
 if(!env?.RESEND_API_KEY||!env?.BOOKING_FROM_EMAIL||!env?.BOOKING_ADMIN_EMAIL)return reply(503,'La notification email administrateur n’est pas encore activée.');
 const admin=env.BOOKING_ADMIN_EMAIL;
 const ref='TD78-'+Date.now().toString(36).toUpperCase()+'-'+crypto.randomUUID().slice(0,6).toUpperCase();
 if(!env?.BOOKINGS_DB)return reply(503,'Le service de réservation est momentanément indisponible.');
 const created=tdNow(),bookingId=crypto.randomUUID();
 try{await env.BOOKINGS_DB.prepare('INSERT INTO bookings(id,reference,created_at,updated_at,customer_name,customer_phone,customer_email,from_address,to_address,travel_date,travel_time,vehicle,return_trip,status,notified) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,0)').bind(bookingId,ref,created,created,b.nom,b.telephone,b.email||null,b.depart,b.destination,b.date,b.heure,b.type,b.retour?1:0,'pending').run();}
 catch{return reply(503,'Impossible d’enregistrer la demande. Merci de réessayer.');}

 const fields=[['Référence',ref],['Statut','EN ATTENTE DE CONFIRMATION'],['Nom',b.nom],['Téléphone',b.telephone],['Email',b.email||'Non communiqué'],['Véhicule demandé',b.type],['Départ',b.depart],['Destination',b.destination],['Date souhaitée',b.date],['Heure souhaitée',b.heure],['Aller-retour',b.retour?'Oui':'Non']];
 const plain=fields.map(([k,v])=>k+' : '+v).join('\n')+'\n\nACTION ADMIN : contacter le client pour confirmer ou refuser selon disponibilité. Aucune réservation n’est confirmée automatiquement.';
 // Escape every client-supplied value before interpolating into HTML.
 const esc=(v)=>String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
 const row=(label,value)=>'<tr><td style="padding:11px 0;border-bottom:1px solid #e9eef2;color:#607487;font:12px Arial,sans-serif;vertical-align:top;width:35%;">'+esc(label)+'</td><td style="padding:11px 0;border-bottom:1px solid #e9eef2;color:#102d41;font:600 14px Arial,sans-serif;vertical-align:top;overflow-wrap:anywhere;word-break:break-word;">'+esc(value)+'</td></tr>';
 const safeTel=b.telephone.replace(/[^+0-9]/g,'');
 const safeDate=/^\d{4}-\d{2}-\d{2}$/.test(b.date)?b.date.slice(8,10)+'/'+b.date.slice(5,7)+'/'+b.date.slice(0,4):b.date;
 const html='<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>'+
 '<body style="margin:0;padding:0;background:#f1f5f8;color:#102d41;font-family:Arial,Helvetica,sans-serif;">'+
 '<div style="display:none;max-height:0;overflow:hidden;opacity:0;">Nouvelle demande de trajet à traiter — '+esc(b.nom)+' — '+esc(safeDate)+' à '+esc(b.heure)+'</div>'+
 '<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="background:#f1f5f8;"><tr><td align="center" style="padding:24px 12px;">'+
 '<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="max-width:620px;background:#ffffff;border-radius:16px;overflow:hidden;">'+
 '<tr><td style="background:#06364e;padding:25px 26px;border-bottom:4px solid #1fb7b0;">'+
 '<div style="color:#ffffff;font-size:26px;line-height:1.2;font-weight:800;letter-spacing:-1px;">Taxi<span style="color:#58d9d3;">Direct</span> <span style="color:#f4c44b;">78</span></div>'+
 '<div style="color:#d0e6ec;font-size:13px;margin-top:7px;">Gestion des demandes de réservation</div></td></tr>'+
 '<tr><td style="padding:25px 26px 8px;">'+
 '<span style="display:inline-block;padding:9px 12px;border-radius:7px;border:1px solid #f2d58c;background:#fff6da;color:#795015;font-size:11px;line-height:1.4;font-weight:800;letter-spacing:.04em;">● EN ATTENTE DE CONFIRMATION</span>'+
 '<h1 style="margin:18px 0 7px;font-size:25px;line-height:1.25;color:#0a2d42;">Nouvelle demande de trajet</h1>'+
 '<p style="margin:0;color:#607487;font-size:14px;line-height:1.65;">Un client souhaite réserver un trajet. Vérifiez les informations puis contactez-le pour confirmer la disponibilité.</p></td></tr>'+
 '<tr><td style="padding:16px 26px 8px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#eef9f8;border:1px solid #cdeae6;border-radius:10px;"><tr><td style="padding:16px;">'+
 '<div style="color:#387b84;font-size:10px;font-weight:800;letter-spacing:.1em;">RÉFÉRENCE DE DEMANDE</div>'+
 '<div style="color:#07374d;font-size:18px;font-weight:800;line-height:1.55;overflow-wrap:anywhere;">'+esc(ref)+'</div>'+
 '</td></tr></table></td></tr>'+
 '<tr><td style="padding:20px 26px 4px;">'+
 '<h2 style="margin:0 0 5px;color:#086c77;font-size:15px;font-weight:800;">01 · Coordonnées du client</h2>'+
 '<table role="presentation" cellpadding="0" cellspacing="0" width="100%">'+
 row('Nom',b.nom)+row('Téléphone',b.telephone)+row('Email',b.email||'Non communiqué')+
 '</table></td></tr>'+
 '<tr><td style="padding:22px 26px 6px;">'+
 '<h2 style="margin:0 0 12px;color:#086c77;font-size:15px;font-weight:800;">02 · Détails du trajet</h2>'+
 '<table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="background:#f6f9fb;border:1px solid #e8eef1;border-radius:10px;"><tr><td style="padding:16px 18px;">'+
 '<div style="font-size:10px;font-weight:800;color:#718794;letter-spacing:.08em;">DÉPART</div>'+
 '<div style="margin-top:5px;font-size:16px;font-weight:800;color:#0d3348;line-height:1.45;overflow-wrap:anywhere;">'+esc(b.depart)+'</div>'+
 '<div style="margin:12px 0 12px;border-left:2px dashed #60c7c3;height:22px;margin-left:4px;"></div>'+
 '<div style="font-size:10px;font-weight:800;color:#718794;letter-spacing:.08em;">DESTINATION</div>'+
 '<div style="margin-top:5px;font-size:16px;font-weight:800;color:#0d3348;line-height:1.45;overflow-wrap:anywhere;">'+esc(b.destination)+'</div>'+
 '</td></tr></table>'+
 '<table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="margin-top:9px;">'+
 row('Date',safeDate)+row('Heure',b.heure)+row('Véhicule',b.type)+row('Aller-retour',b.retour?'Oui':'Non')+
 '</table></td></tr>'+
 '<tr><td style="padding:18px 26px 6px;"><table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="background:#fff9e9;border:1px solid #f5e5ac;border-radius:10px;"><tr><td style="padding:17px 18px;">'+
 '<div style="font-size:13px;color:#76500e;font-weight:800;margin-bottom:7px;">03 · Action administrateur</div>'+
 '<div style="font-size:13px;color:#594826;line-height:1.7;">Contactez le client pour <strong>confirmer ou refuser</strong> la course selon les disponibilités. Aucune réservation n’est confirmée automatiquement.</div>'+
 '</td></tr></table></td></tr>'+
 '<tr><td align="center" style="padding:23px 26px 29px;">'+
 '<a href="tel:'+esc(safeTel)+'" style="display:block;text-align:center;background:#076f78;color:#ffffff;text-decoration:none;border-radius:9px;padding:16px 18px;font-size:15px;font-weight:800;">Appeler le client · '+esc(b.telephone)+'</a>'+
 (b.email?'<div style="margin-top:15px;font-size:13px;"><a href="mailto:'+esc(b.email)+'" style="color:#087a82;text-decoration:underline;">Écrire au client par email</a></div>':'')+
 '</td></tr>'+
 '<tr><td style="background:#f5f8fa;padding:18px 24px;text-align:center;color:#6b8090;font-size:11px;line-height:1.65;">Notification automatique TaxiDirect 78 · Demande non confirmée<br>Ce message contient des informations destinées à la gestion de la réservation.</td></tr>'+
 '</table></td></tr></table></body></html>';
 let send;
 try{send=await fetch('https://api.resend.com/emails',{method:'POST',headers:{'Authorization':'Bearer '+env.RESEND_API_KEY,'Content-Type':'application/json'},body:JSON.stringify({from:env.BOOKING_FROM_EMAIL,to:[admin],subject:'TaxiDirect 78 · Nouvelle demande à confirmer · '+ref,text:plain,html})});}
 catch{return reply(202,'Demande enregistrée dans le tableau de bord. Notification email momentanément indisponible.',{reference:ref,status:'pending',emailSent:false});}
 if(!send.ok)return reply(202,'Demande enregistrée dans le tableau de bord, mais notification email indisponible.',{reference:ref,status:'pending',emailSent:false});
 await env.BOOKINGS_DB.prepare('UPDATE bookings SET notified=1 WHERE id=?').bind(bookingId).run();
 return reply(202,'Demande transmise à TaxiDirect. En attente de confirmation.',{reference:ref,status:'pending',emailSent:true});
}

/* Private TaxiDirect dispatch API. All authenticated routes deny unauthenticated access. */
const TDJSON={'content-type':'application/json;charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff'};
const tdReply=(code,obj,extra={})=>new Response(JSON.stringify(obj),{status:code,headers:{...TDJSON,...extra}});
const tdHash=async(value)=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value)))).map(x=>x.toString(16).padStart(2,'0')).join('');
const tdClean=(v,max)=>typeof v==='string'?v.trim().slice(0,max):'';
const tdEmail=(v)=>typeof v==='string'?v.trim().toLowerCase():'';
const tdNow=()=>new Date().toISOString();
const tdCookie=(r)=>{const m=(r.headers.get('Cookie')||'').match(/(?:^|;\s*)td78_session=([^;]+)/);return m?.[1]||''};
const tdSameOrigin=(r)=>{try{return new URL(r.headers.get('Origin')||'').origin===new URL(r.url).origin}catch{return false}};
async function tdInput(r){if(!/application\/json/i.test(r.headers.get('content-type')||''))throw Error('Format invalide');const str=await r.text();if(str.length>10000)throw Error('Requête trop volumineuse');const x=JSON.parse(str);if(!x||Array.isArray(x)||typeof x!=='object')throw Error('Données invalides');return x}
async function tdIdentity(env,id){const identifier=tdEmail(id);if(!identifier||identifier.length>140)return null; if(identifier===tdEmail(env.BOOKING_ADMIN_EMAIL))return {identifier,email:tdEmail(env.BOOKING_ADMIN_EMAIL),role:'admin',driver_id:null,name:'Administrateur TaxiDirect'};const driver=await env.BOOKINGS_DB.prepare('SELECT id,display_name,email FROM drivers WHERE active=1 AND (lower(email)=? OR lower(id)=?)').bind(identifier,identifier).first();return driver?{identifier,email:driver.email.toLowerCase(),role:'driver',driver_id:driver.id,name:driver.display_name}:null}
async function tdSession(r,env){const token=tdCookie(r);if(!/^[a-f0-9]{64}$/.test(token))return null;const hash=await tdHash(token);const row=await env.BOOKINGS_DB.prepare('SELECT * FROM sessions WHERE token_hash=? AND expires_at>?').bind(hash,Date.now()).first();if(!row)return null;if(row.role==='admin'){if(tdEmail(row.identity)!==tdEmail(env.BOOKING_ADMIN_EMAIL))return null;return {role:'admin',email:row.identity,name:'Administrateur TaxiDirect',driver_id:null}}const drv=await env.BOOKINGS_DB.prepare('SELECT id,display_name,email FROM drivers WHERE id=? AND active=1 AND lower(email)=?').bind(row.driver_id,tdEmail(row.identity)).first();return drv?{role:'driver',email:drv.email,name:drv.display_name,driver_id:drv.id}:null}
const tdAudit=async(db,booking,actor,action,details)=>db.prepare('INSERT INTO audit_log(id,booking_id,actor,action,details,created_at) VALUES(?,?,?,?,?,?)').bind(crypto.randomUUID(),booking,actor,action,details,tdNow()).run();
async function tdAuthApi(request,env,path){
 if(!env?.BOOKINGS_DB)return tdReply(503,{error:'Service de gestion indisponible'});
 const method=request.method;
 if(path==='/api/auth/me'){const actor=await tdSession(request,env);return actor?tdReply(200,{user:actor}):tdReply(401,{error:'Connexion nécessaire'})}
 if(path==='/api/auth/start'&&method==='POST'){
  if(!tdSameOrigin(request))return tdReply(403,{error:'Origine non autorisée'});
  let input;try{input=await tdInput(request)}catch{return tdReply(400,{error:'Données incorrectes'})}
  const key=tdEmail(input.identifier);const identity=await tdIdentity(env,key);
  const generic={message:'Si cet identifiant est autorisé, un code de connexion a été envoyé.'};
  if(!identity||!env.RESEND_API_KEY||!env.BOOKING_FROM_EMAIL)return tdReply(200,generic);
  const previous=await env.BOOKINGS_DB.prepare('SELECT last_sent_at FROM login_codes WHERE identifier=?').bind(key).first();
  if(previous&&Date.now()-previous.last_sent_at<90000)return tdReply(200,generic);
  const bytes=new Uint32Array(1);crypto.getRandomValues(bytes);const code=String(bytes[0]%1000000).padStart(6,'0');
  const salt=crypto.randomUUID();const digest=await tdHash(salt+':'+code);
  const mailed=await fetch('https://api.resend.com/emails',{method:'POST',headers:{Authorization:'Bearer '+env.RESEND_API_KEY,'Content-Type':'application/json'},body:JSON.stringify({from:env.BOOKING_FROM_EMAIL,to:[identity.email],subject:'TaxiDirect 78 · Votre code de connexion',text:'Votre code de connexion TaxiDirect 78 : '+code+'\n\nValable 10 minutes. Ne communiquez ce code à personne. Si vous n’avez pas demandé cette connexion, ignorez cet email.',html:'<div style="font-family:Arial,sans-serif;max-width:420px;margin:auto;padding:25px;background:#f4f8fa"><div style="background:#06364e;color:white;padding:22px;border-radius:12px 12px 0 0;font-size:24px;font-weight:bold">Taxi<span style="color:#60dcd3">Direct</span> <span style="color:#f4c44b">78</span></div><div style="padding:25px;background:white"><h2 style="color:#133b4b">Code de connexion</h2><p>Voici votre code à usage unique :</p><div style="font-weight:900;letter-spacing:6px;font-size:34px;color:#087c82;text-align:center;padding:17px;background:#eef8f7;border-radius:10px">'+code+'</div><p style="color:#526571;font-size:13px">Valable 10 minutes. Ne partagez jamais ce code.</p></div></div>'})});
  if(mailed.ok)await env.BOOKINGS_DB.prepare('INSERT INTO login_codes(identifier,code_hash,expires_at,last_sent_at,attempts) VALUES(?,?,?,?,0) ON CONFLICT(identifier) DO UPDATE SET code_hash=excluded.code_hash,expires_at=excluded.expires_at,last_sent_at=excluded.last_sent_at,attempts=0').bind(key,salt+':'+digest,Date.now()+600000,Date.now()).run();
  return tdReply(200,generic);
 }
 if(path==='/api/auth/verify'&&method==='POST'){
  if(!tdSameOrigin(request))return tdReply(403,{error:'Origine non autorisée'});
  let data;try{data=await tdInput(request)}catch{return tdReply(400,{error:'Données incorrectes'})}
  const key=tdEmail(data.identifier),otp=tdClean(data.code,10);if(!/^\d{6}$/.test(otp))return tdReply(422,{error:'Code à six chiffres requis'});
  const row=await env.BOOKINGS_DB.prepare('SELECT * FROM login_codes WHERE identifier=?').bind(key).first();
  if(!row||row.expires_at<Date.now()||row.attempts>=5)return tdReply(401,{error:'Code expiré ou incorrect'});
  await env.BOOKINGS_DB.prepare('UPDATE login_codes SET attempts=attempts+1 WHERE identifier=?').bind(key).run();
  const [salt,digest]=row.code_hash.split(':');if((await tdHash(salt+':'+otp))!==digest)return tdReply(401,{error:'Code expiré ou incorrect'});
  const actor=await tdIdentity(env,key);if(!actor)return tdReply(403,{error:'Compte non autorisé'});
  await env.BOOKINGS_DB.prepare('DELETE FROM login_codes WHERE identifier=?').bind(key).run();
  const buf=crypto.getRandomValues(new Uint8Array(32));const token=Array.from(buf).map(v=>v.toString(16).padStart(2,'0')).join('');
  await env.BOOKINGS_DB.prepare('INSERT INTO sessions(token_hash,identity,role,driver_id,expires_at,created_at) VALUES(?,?,?,?,?,?)').bind(await tdHash(token),actor.email,actor.role,actor.driver_id,Date.now()+604800000,tdNow()).run();
  return tdReply(200,{user:actor},{'set-cookie':'td78_session='+token+'; Path=/; Secure; HttpOnly; SameSite=Strict; Max-Age=604800'});
 }
 if(path==='/api/auth/logout'&&method==='POST'){
  if(!tdSameOrigin(request))return tdReply(403,{error:'Origine non autorisée'});
  const token=tdCookie(request);if(token)await env.BOOKINGS_DB.prepare('DELETE FROM sessions WHERE token_hash=?').bind(await tdHash(token)).run();
  return tdReply(200,{ok:true},{'set-cookie':'td78_session=; Path=/; Secure; HttpOnly; SameSite=Strict; Max-Age=0'});
 }
 return tdReply(404,{error:'Introuvable'});
}
async function tdDispatchApi(request,env,path){
 if(!env?.BOOKINGS_DB)return tdReply(503,{error:'Base de données indisponible'});
 const actor=await tdSession(request,env);if(!actor)return tdReply(401,{error:'Connexion nécessaire'});
 if(request.method!=='GET'&&!tdSameOrigin(request))return tdReply(403,{error:'Origine non autorisée'});
 const db=env.BOOKINGS_DB;
 if(path==='/api/dispatch/overview'&&request.method==='GET'){
  const [stats,bookings,drivers]=await Promise.all([
   db.prepare("SELECT status,COUNT(*) AS total FROM bookings GROUP BY status").all(),
   actor.role==='admin'?db.prepare('SELECT b.*,d.display_name AS driver_name FROM bookings b LEFT JOIN drivers d ON d.id=b.driver_id ORDER BY b.created_at DESC LIMIT 150').all():db.prepare('SELECT b.*,d.display_name AS driver_name FROM bookings b LEFT JOIN drivers d ON d.id=b.driver_id WHERE b.driver_id=? AND b.status IN (\'confirmed\',\'on_route\',\'completed\') ORDER BY b.travel_date ASC,b.travel_time ASC LIMIT 100').bind(actor.driver_id).all(),
   actor.role==='admin'?db.prepare('SELECT id,display_name,email,phone,active,created_at FROM drivers ORDER BY created_at DESC').all():Promise.resolve({results:[]})
  ]);
  const safe=(bookings.results||[]).map(x=>({...x,notes:actor.role==='admin'?x.notes:null}));
  return tdReply(200,{user:actor,stats:actor.role==='admin'?(stats.results||[]):[],bookings:safe,drivers:drivers.results||[]});
 }
 if(path==='/api/dispatch/drivers'&&request.method==='POST'&&actor.role==='admin'){
  let x;try{x=await tdInput(request)}catch{return tdReply(400,{error:'Données invalides'})}
  const name=tdClean(x.name,85),email=tdEmail(x.email),phone=tdClean(x.phone,30);
  if(name.length<2||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)||!/^([+0-9() .-]{8,30})?$/.test(phone))return tdReply(422,{error:'Vérifiez nom, email et téléphone'});
  const driverId='TD-CH-'+crypto.randomUUID().slice(0,8).toUpperCase();
  try{await db.prepare('INSERT INTO drivers(id,display_name,email,phone,active,created_at) VALUES(?,?,?,?,1,?)').bind(driverId,name,email,phone,tdNow()).run();}catch{return tdReply(409,{error:'Un chauffeur utilise déjà cette adresse email'})}
  await tdAudit(db,null,actor.email,'driver_created',driverId);
  return tdReply(201,{ok:true,id:driverId});
 }
 const drvPath=path.match(/^\/api\/dispatch\/drivers\/(TD-CH-[A-F0-9]{8})$/);
 if(drvPath&&request.method==='PATCH'&&actor.role==='admin'){
  let x;try{x=await tdInput(request)}catch{return tdReply(400,{error:'Données incorrectes'})}
  const active=x.active===true?1:x.active===false?0:null;if(active===null)return tdReply(422,{error:'Statut invalide'});
  const z=await db.prepare('UPDATE drivers SET active=? WHERE id=?').bind(active,drvPath[1]).run();if(!z.meta?.changes)return tdReply(404,{error:'Chauffeur introuvable'});
  if(!active)await db.prepare('DELETE FROM sessions WHERE driver_id=?').bind(drvPath[1]).run();
  await tdAudit(db,null,actor.email,'driver_access_changed',drvPath[1]+':'+active);return tdReply(200,{ok:true});
 }
 const match=path.match(/^\/api\/dispatch\/bookings\/(TD78-[A-Z0-9-]+)$/);
 if(match&&request.method==='PATCH'){
  let x;try{x=await tdInput(request)}catch{return tdReply(400,{error:'Données incorrectes'})}
  const booking=await db.prepare('SELECT * FROM bookings WHERE reference=?').bind(match[1]).first();if(!booking)return tdReply(404,{error:'Réservation introuvable'});
  if(actor.role==='driver'){
   if(booking.driver_id!==actor.driver_id)return tdReply(403,{error:'Course non attribuée'});
   const next=tdClean(x.status,24),allowed={confirmed:['on_route'],on_route:['completed']};
   if(!(allowed[booking.status]||[]).includes(next))return tdReply(409,{error:'Transition non autorisée'});
   const updated=await db.prepare('UPDATE bookings SET status=?,updated_at=? WHERE reference=? AND status=? AND driver_id=?').bind(next,tdNow(),booking.reference,booking.status,actor.driver_id).run();
   if(!updated.meta?.changes)return tdReply(409,{error:'Statut modifié entre-temps'});
   await tdAudit(db,booking.id,actor.email,'status',booking.status+' -> '+next);return tdReply(200,{ok:true,status:next});
  }
  const status=tdClean(x.status,24),assign=tdClean(x.driver_id,20),notes=tdClean(x.notes,450);
  if(x.action==='assign'){
   if(!['pending','confirmed'].includes(booking.status))return tdReply(409,{error:'Course non attribuable'});
   if(assign){const drv=await db.prepare('SELECT id FROM drivers WHERE id=? AND active=1').bind(assign).first();if(!drv)return tdReply(422,{error:'Chauffeur indisponible'})}
   await db.prepare('UPDATE bookings SET driver_id=?,updated_at=? WHERE reference=?').bind(assign||null,tdNow(),booking.reference).run();
   await tdAudit(db,booking.id,actor.email,'assigned',assign||'unassigned');return tdReply(200,{ok:true});
  }
  if(x.action==='notes'){await db.prepare('UPDATE bookings SET notes=?,updated_at=? WHERE reference=?').bind(notes,tdNow(),booking.reference).run();await tdAudit(db,booking.id,actor.email,'notes_updated','Notes internes');return tdReply(200,{ok:true})}
  const allowed={pending:['confirmed','rejected'],confirmed:['cancelled','on_route'],on_route:['completed','cancelled']};
  if(!(allowed[booking.status]||[]).includes(status))return tdReply(409,{error:'Transition non autorisée'});
  const updated=await db.prepare('UPDATE bookings SET status=?,updated_at=?,decision_at=?,decision_by=? WHERE reference=? AND status=?').bind(status,tdNow(),tdNow(),actor.email,booking.reference,booking.status).run();
  if(!updated.meta?.changes)return tdReply(409,{error:'Statut modifié entre-temps'});
  await tdAudit(db,booking.id,actor.email,'status',booking.status+' -> '+status);
  return tdReply(200,{ok:true,status,clientNotified:false});
 }
 return tdReply(404,{error:'Action inconnue ou non autorisée'});
}
function tdDashboardHtml(){return "<!doctype html><html lang=\"fr\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"robots\" content=\"noindex,nofollow\"><title>TaxiDirect 78 · Espace professionnel</title>\n<style>\n*{box-sizing:border-box}body{margin:0;background:#f1f6f8;color:#092a3f;font:14px/1.5 Arial,sans-serif}h1,h2{margin:0 0 13px}header{background:#07334a;color:#fff;display:flex;justify-content:space-between;align-items:center;padding:18px max(15px,calc((100vw - 1100px)/2));gap:12px}.brand{font-size:24px;letter-spacing:-1px;font-style:italic;font-weight:900}.brand span{color:#52dad0}.brand b{color:#f3c34b}.wrap{max-width:1100px;margin:auto;padding:24px 14px 50px}.card,.stat,.booking{background:white;border:1px solid #dbe6ea;border-radius:14px;padding:17px;box-shadow:0 5px 20px #173f4e0a}.login{max-width:410px;margin:45px auto}.sub{color:#708898;font-size:12px;line-height:1.6}.eyebrow{color:#028d8b;font-size:11px;font-weight:900;letter-spacing:.1em}label{display:block;font-weight:800;font-size:12px;margin:12px 0 5px}input,select,textarea{font:inherit;color:#092a3f;border:1px solid #cbdbe3;border-radius:8px;padding:11px;min-height:42px;width:100%;background:white}.btn{font:800 12px Arial,sans-serif;cursor:pointer;border:0;border-radius:9px;padding:11px 14px;min-height:39px;background:#087d84;color:white}.btn:disabled{opacity:.5}.ghost{background:#e9f2f4;color:#184456}.danger{background:#fce9e9;color:#a12e2e}.small{font-size:11px;padding:7px 10px;min-height:33px}.wide{width:100%;margin-top:14px}.hidden{display:none!important}.feedback{color:#07827d;font-weight:800;font-size:12px}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:11px;margin:17px 0 20px}.stat strong{font-size:29px;display:block}.stat small{color:#71909e}.tabs,.tools,.buttons{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px;align-items:center}.tools input,.tools select{width:auto;flex:1;min-width:150px;max-width:270px}.bookings{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.booking{min-width:0}.line{display:flex;justify-content:space-between;align-items:start;gap:10px}.ref{color:#728b9a;font-size:10px;word-break:break-word}.pill{padding:5px 8px;border-radius:20px;font-size:10px;font-weight:900;background:#edf2f4;white-space:nowrap}.pill.pending{background:#fff0c5;color:#876000}.pill.confirmed{background:#def3e8;color:#126c41}.pill.rejected,.pill.cancelled{background:#fde4e4;color:#9c3131}.pill.on_route{background:#dfedff;color:#3466a4}.pill.completed{background:#ece8fa;color:#5847a1}.route{font-size:17px;font-weight:900;line-height:1.4;margin:13px 0;overflow-wrap:anywhere}.route em{color:#009e9e}.tags{display:flex;gap:6px;flex-wrap:wrap}.tags span{font-size:11px;background:#f1f6f8;padding:5px 8px;border-radius:6px;color:#35576b}.fields{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin:13px 0}.fields small{color:#76909e;display:block;font-weight:800;font-size:10px}.fields div{font-size:12px;overflow-wrap:anywhere}.fields a{color:#077e86}.assign{display:flex;gap:7px;margin:12px 0}.assign select{min-width:0;flex:1}.driversForm{display:grid;grid-template-columns:1fr 1fr 1fr auto;gap:9px;align-items:end}.driversForm label{margin:0}.driversList{display:grid;gap:9px;margin-top:16px}.driver{padding:13px;border:1px solid #d8e5ea;border-radius:9px;display:flex;justify-content:space-between;align-items:center;gap:10px}.driver code{display:block;font-size:11px;color:#007d86;font-weight:bold}.driver small{display:block;color:#7e919f}.hint{font-size:11px;padding:12px;border:1px solid #f0dc9f;border-radius:9px;background:#fff8e4;color:#796028;margin-top:16px}.empty{grid-column:1/-1;text-align:center;padding:30px;color:#7992a0;background:white;border:1px dashed #b2c9d4;border-radius:12px}@media(max-width:700px){.bookings{grid-template-columns:1fr}.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.driversForm{grid-template-columns:1fr 1fr}.driversForm button{grid-column:1/-1}}@media(max-width:430px){.wrap{padding:15px 11px 38px}.driversForm{grid-template-columns:1fr}.tools input,.tools select{max-width:none;width:100%}.card,.booking{padding:13px}.brand{font-size:20px}.stat strong{font-size:25px}}\n</style></head><body>\n<header><div class=\"brand\">Taxi<span>Direct</span> <b>78</b></div><div><span id=\"who\" style=\"font-size:11px\"></span> <button id=\"logout\" class=\"btn ghost small hidden\">Déconnexion</button></div></header><main class=\"wrap\">\n<section id=\"login\" class=\"card login\"><div class=\"eyebrow\">ESPACE PROFESSIONNEL SÉCURISÉ</div><h1>Bienvenue à bord.</h1><p class=\"sub\">Connectez-vous avec votre adresse email ou votre identifiant chauffeur. Un code temporaire vous sera envoyé par email.</p><form id=\"start\"><label>Adresse email / identifiant chauffeur</label><input id=\"identifier\" required autocomplete=\"username\" placeholder=\"Email ou TD-CH-XXXXXXXX\"><button class=\"btn wide\">Recevoir le code</button></form><form id=\"verify\" class=\"hidden\"><label>Code de connexion (6 chiffres)</label><input id=\"otp\" required pattern=\"[0-9]{6}\" maxlength=\"6\" inputmode=\"numeric\" autocomplete=\"one-time-code\"><button class=\"btn wide\">Se connecter</button><button type=\"button\" class=\"btn ghost wide\" id=\"other\">Changer d’identifiant</button></form><p id=\"authMessage\" class=\"feedback\" role=\"status\"></p><p class=\"sub\">Accès réservé aux personnes autorisées.</p></section>\n<section id=\"app\" class=\"hidden\"><div class=\"eyebrow\" id=\"role\">GESTION</div><h1 id=\"title\">Tableau de bord</h1><p class=\"sub\">Gestion des demandes, chauffeurs et suivi des courses.</p><div id=\"stats\" class=\"grid\"></div><div class=\"tabs\"><button id=\"bookingTab\" class=\"btn\">Réservations</button><button id=\"driversTab\" class=\"btn ghost hidden\">Chauffeurs</button><button id=\"refresh\" class=\"btn ghost\">↻ Actualiser</button></div>\n<div id=\"bookingView\"><div class=\"tools\"><input id=\"search\" placeholder=\"Client, ville, référence…\"><select id=\"statusFilter\"><option value=\"\">Tous les statuts</option><option value=\"pending\">En attente</option><option value=\"confirmed\">Confirmée</option><option value=\"on_route\">En cours</option><option value=\"completed\">Terminée</option><option value=\"rejected\">Refusée</option><option value=\"cancelled\">Annulée</option></select><input id=\"dateFilter\" type=\"date\" aria-label=\"Date du trajet\"></div><div id=\"bookingList\" class=\"bookings\"></div><p class=\"sub\" id=\"count\"></p></div>\n<div id=\"driversView\" class=\"card hidden\"><h2>Gestion des chauffeurs</h2><p class=\"sub\">Chaque chauffeur dispose d’un identifiant unique et reçoit un code temporaire à son adresse email.</p><form id=\"newDriver\" class=\"driversForm\"><label>Nom<input name=\"name\" required></label><label>Email<input name=\"email\" type=\"email\" required></label><label>Téléphone<input name=\"phone\" type=\"tel\"></label><button class=\"btn\">+ Ajouter</button></form><p class=\"feedback\" id=\"driverMessage\"></p><div class=\"driversList\" id=\"driverList\"></div><div class=\"hint\">Pour envoyer les codes aux chauffeurs externes, il faudra authentifier le domaine d’expédition Resend. L’adresse de test actuelle peut être limitée.</div></div>\n</section><p class=\"sub\" style=\"text-align:center;margin:30px auto\">TaxiDirect 78 · Données confidentielles · Confirmation des courses par un responsable</p></main>\n<script>\n(function(){\nconst $=id=>document.getElementById(id);const show=(id,val)=>$(id).classList.toggle('hidden',!val);const esc=x=>String(x??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));const state={user:null,bookings:[],drivers:[]};const labels={pending:'En attente',confirmed:'Confirmée',rejected:'Refusée',cancelled:'Annulée',on_route:'En route',completed:'Terminée'};\nasync function api(path,options={}){const r=await fetch(path,{credentials:'same-origin',...options,headers:{...(options.body?{'content-type':'application/json'}:{}),...options.headers}});const data=await r.json().catch(()=>({}));if(!r.ok)throw Error(data.error||'Erreur '+r.status);return data}\nfunction loggedOut(){state.user=null;show('login',true);show('app',false);show('logout',false)}\nasync function loggedIn(user){state.user=user;show('login',false);show('app',true);show('logout',true);show('driversTab',user.role==='admin');$('who').textContent=user.name;$('title').textContent=user.role==='admin'?'Tableau de bord administrateur':'Mes courses attribuées';$('role').textContent=user.role==='admin'?'ADMINISTRATION':'CHAUFFEUR';await refresh()}\nasync function refresh(){try{const d=await api('/api/dispatch/overview');state.bookings=d.bookings||[];state.drivers=d.drivers||[];render()}catch(e){if(e.message.includes('Connexion'))loggedOut();else alert(e.message)}}\nfunction render(){const c=k=>state.bookings.filter(b=>b.status===k).length;const values=state.user.role==='admin'?[['En attente',c('pending')],['Confirmées',c('confirmed')],['En cours',c('on_route')],['Terminées',c('completed')]]:[['Attribuées',state.bookings.length],['À faire',c('confirmed')],['En route',c('on_route')],['Terminées',c('completed')]];$('stats').innerHTML=values.map(v=>'<div class=\"stat\"><strong>'+v[1]+'</strong><small>'+v[0]+'</small></div>').join('');drawBookings();drawDrivers()}\nfunction drawBookings(){const q=$('search').value.toLowerCase(),stat=$('statusFilter').value,day=$('dateFilter').value,admin=state.user.role==='admin';const list=state.bookings.filter(b=>(!stat||stat===b.status)&&(!day||day===b.travel_date)&&(!q||[b.reference,b.customer_name,b.from_address,b.to_address].some(v=>String(v||'').toLowerCase().includes(q))));$('count').textContent=list.length+' course(s) affichée(s)';$('bookingList').innerHTML=list.length?list.map(b=>{const ref=esc(b.reference),tel=esc(String(b.customer_phone||'').replace(/[^0-9+]/g,''));let actions='';if(admin){if(b.status==='pending')actions='<button class=\"btn small\" data-op=\"confirmed\" data-ref=\"'+ref+'\">✓ Confirmer</button> <button class=\"btn small danger\" data-op=\"rejected\" data-ref=\"'+ref+'\">Refuser</button>';else if(b.status==='confirmed')actions='<button class=\"btn small danger\" data-op=\"cancelled\" data-ref=\"'+ref+'\">Annuler</button>';}else{if(b.status==='confirmed')actions='<button class=\"btn small\" data-op=\"on_route\" data-ref=\"'+ref+'\">Départ effectué</button>';else if(b.status==='on_route')actions='<button class=\"btn small\" data-op=\"completed\" data-ref=\"'+ref+'\">Course terminée</button>';}const select=admin?'<div class=\"assign\"><select data-select=\"'+ref+'\"><option value=\"\">Non attribuée</option>'+state.drivers.filter(d=>d.active||d.id===b.driver_id).map(d=>'<option '+(d.id===b.driver_id?'selected':'')+' value=\"'+esc(d.id)+'\">'+esc(d.display_name)+'</option>').join('')+'</select><button class=\"btn small ghost\" data-op=\"assign\" data-ref=\"'+ref+'\">Affecter</button></div>':'';return '<article class=\"booking\"><div class=\"line\"><span class=\"ref\">'+ref+'</span><span class=\"pill '+esc(b.status)+'\">'+(labels[b.status]||'Statut')+'</span></div><div class=\"route\">'+esc(b.from_address)+' <em>→</em> '+esc(b.to_address)+'</div><div class=\"tags\"><span>'+esc(b.travel_date)+'</span><span>'+esc(b.travel_time)+'</span><span>'+esc(b.vehicle)+'</span><span>'+(b.return_trip?'Aller-retour':'Aller simple')+'</span></div><div class=\"fields\"><div><small>CLIENT</small>'+esc(b.customer_name)+'</div><div><small>TÉLÉPHONE</small><a href=\"tel:'+tel+'\">'+esc(b.customer_phone)+'</a></div><div><small>EMAIL</small>'+esc(b.customer_email||'Non communiqué')+'</div><div><small>CHAUFFEUR</small>'+esc(b.driver_name||'Non attribué')+'</div></div>'+select+'<div class=\"buttons\">'+actions+' <a class=\"btn small ghost\" href=\"tel:'+tel+'\">Appeler</a></div>'+(admin?'<label>Note interne</label><textarea data-note=\"'+ref+'\" rows=\"2\" maxlength=\"450\">'+esc(b.notes||'')+'</textarea><button class=\"btn small ghost\" data-op=\"notes\" data-ref=\"'+ref+'\">Sauvegarder</button>':'')+'</article>'}).join(''):'<div class=\"empty\">Aucune course correspondant aux filtres.</div>'}\nfunction drawDrivers(){$('driverList').innerHTML=state.drivers.length?state.drivers.map(d=>'<div class=\"driver\"><div><strong>'+esc(d.display_name)+'</strong><small>'+esc(d.email)+'</small><code>'+esc(d.id)+'</code></div><button class=\"btn small '+(d.active?'danger':'ghost')+'\" data-id=\"'+esc(d.id)+'\" data-active=\"'+(d.active?'0':'1')+'\">'+(d.active?'Désactiver':'Activer')+'</button></div>').join(''):'<div class=\"empty\">Aucun compte chauffeur.</div>'}\n$('start').onsubmit=async e=>{e.preventDefault();try{const r=await api('/api/auth/start',{method:'POST',body:JSON.stringify({identifier:$('identifier').value})});$('authMessage').textContent=r.message;show('start',false);show('verify',true)}catch(x){$('authMessage').textContent=x.message}};\n$('verify').onsubmit=async e=>{e.preventDefault();try{const r=await api('/api/auth/verify',{method:'POST',body:JSON.stringify({identifier:$('identifier').value,code:$('otp').value})});await loggedIn(r.user)}catch(x){$('authMessage').textContent=x.message}};\n$('other').onclick=()=>{show('start',true);show('verify',false);$('authMessage').textContent=''};\n$('logout').onclick=async()=>{await api('/api/auth/logout',{method:'POST',body:'{}'}).catch(()=>null);loggedOut()};\n$('refresh').onclick=refresh;$('search').oninput=drawBookings;$('statusFilter').onchange=drawBookings;$('dateFilter').onchange=drawBookings;\n$('bookingTab').onclick=()=>{show('bookingView',true);show('driversView',false)};$('driversTab').onclick=()=>{show('bookingView',false);show('driversView',true)};\n$('newDriver').onsubmit=async e=>{e.preventDefault();try{const r=await api('/api/dispatch/drivers',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});$('driverMessage').textContent='Chauffeur créé : '+r.id;e.target.reset();await refresh()}catch(x){$('driverMessage').textContent=x.message}};\n$('driverList').onclick=async e=>{const btn=e.target.closest('[data-id]');if(!btn)return;const active=btn.dataset.active==='1';if(!confirm(active?'Réactiver ce chauffeur ?':'Désactiver ce chauffeur ?'))return;try{await api('/api/dispatch/drivers/'+btn.dataset.id,{method:'PATCH',body:JSON.stringify({active})});await refresh()}catch(x){alert(x.message)}};\n$('bookingList').onclick=async e=>{const btn=e.target.closest('[data-op]');if(!btn)return;const ref=btn.dataset.ref,op=btn.dataset.op;let data;if(op==='assign')data={action:'assign',driver_id:document.querySelector('[data-select=\"'+ref+'\"]').value};else if(op==='notes')data={action:'notes',notes:document.querySelector('[data-note=\"'+ref+'\"]').value};else{if(!confirm('Confirmer ce changement de statut ? Il faut prévenir le client séparément.'))return;data={status:op}}btn.disabled=true;try{await api('/api/dispatch/bookings/'+ref,{method:'PATCH',body:JSON.stringify(data)});if(op==='confirmed')alert('Course confirmée dans le dashboard. Contactez le client pour le prévenir.');await refresh()}catch(x){alert(x.message)}finally{btn.disabled=false}};\napi('/api/auth/me').then(r=>loggedIn(r.user)).catch(loggedOut);\n})();</script></body></html>";}
