  const activeMenuCSS="\n/* Clear, accessible current-page navigation – desktop + mobile. */\n.f-nav>a,.f-nav .nav-drop>button{border-radius:11px!important;border-bottom:0!important;position:relative!important;transition:color .22s ease,background-color .22s ease,box-shadow .22s ease!important}\n.f-nav>a.nav-current,.f-nav .nav-drop>button.nav-current{color:#007e84!important;background:linear-gradient(135deg,rgba(7,189,183,.16),rgba(7,189,183,.055))!important;box-shadow:inset 0 0 0 1px rgba(5,172,169,.2)!important;font-weight:850!important}\n.f-nav>a.nav-current::after,.f-nav .nav-drop>button.nav-current::after{content:\"\";position:absolute;bottom:3px;left:12px;right:12px;height:3px;border-radius:5px;background:linear-gradient(90deg,#10c9bf,#f1bd52);box-shadow:0 1px 9px rgba(6,177,173,.35)}\n.f-nav>a:hover,.f-nav .nav-drop>button:hover{color:#008b89!important;background:rgba(3,184,179,.09)!important}\n.f-nav .nav-panel a[aria-current=\"page\"]{color:#006f76!important;background:#e4f7f5!important;box-shadow:inset 3px 0 #13b8ac;font-weight:900!important}\n.f-mobile-nav nav a[aria-current=\"page\"]{color:#007c83!important;background:linear-gradient(90deg,#dcf7f3,#f2fbfa)!important;border-left:4px solid #04b6ad!important;padding-left:14px!important;font-weight:900!important;border-radius:8px}\n@media(prefers-reduced-motion:reduce){.f-nav>a,.f-nav .nav-drop>button{transition:none!important}}\n";
