  const bookingPageChoiceCSS="\n/* Réservation complète : mêmes pictogrammes et sélection claire que sur l'accueil */\n.book .f-booking-vehicle-fieldset{border:0;padding:0;margin:7px 0 18px;min-width:0}\n.book .f-booking-vehicle-fieldset legend{font-size:13px;font-weight:900;color:#103749;padding:0;margin:0 0 10px}\n.book .f-choose-type{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:10px!important;margin:0!important}\n.book .f-choice{position:relative!important;display:block!important;margin:0!important;min-width:0!important;cursor:pointer!important}\n.book .f-choice input[type=\"radio\"]{position:absolute!important;left:0!important;top:0!important;opacity:0!important;width:1px!important;height:1px!important;min-height:1px!important;padding:0!important;border:0!important;pointer-events:none!important}\n.book .f-choice>span{display:grid!important;grid-template-columns:43px minmax(0,1fr)!important;grid-template-rows:auto auto!important;gap:2px 9px!important;align-items:center!important;padding:12px 10px!important;min-height:77px!important;border:1px solid #cfdee3!important;border-radius:13px!important;background:#fff!important;box-shadow:0 4px 12px rgba(12,61,73,.07)!important}\n.book .f-choice .f-vehicle-icon{grid-row:1/3!important;grid-column:1!important;width:42px;height:42px;display:grid;place-items:center;border-radius:12px;background:#e8f8f5;color:#057d84!important}\n.book .f-choice .f-vehicle-icon svg{width:32px!important;height:32px!important;stroke:currentColor;stroke-width:1.8}\n.book .f-choice b{grid-row:1!important;grid-column:2!important;font-weight:900!important;font-size:12px!important;line-height:1.25!important;color:#123949!important}\n.book .f-choice small{grid-row:2!important;grid-column:2!important;font-weight:600!important;font-size:10px!important;line-height:1.3!important;color:#637d87!important}\n.book .f-choice input[type=\"radio\"]:checked+span{background:linear-gradient(125deg,#076e7e,#0aa6a3)!important;border-color:#0fcbbd!important;box-shadow:0 6px 17px rgba(4,130,134,.2)!important}\n.book .f-choice input[type=\"radio\"]:checked+span .f-vehicle-icon{background:rgba(255,255,255,.16)!important;color:white!important}\n.book .f-choice input[type=\"radio\"]:checked+span b,.book .f-choice input[type=\"radio\"]:checked+span small{color:#fff!important}\n.book .f-choice input[type=\"radio\"]:focus-visible+span{outline:3px solid #f2bd41!important;outline-offset:3px}\n.book .f-choice:hover>span{border-color:#0eaaa7!important}\n@media(max-width:460px){.book .f-choose-type{gap:8px!important}.book .f-choice>span{grid-template-columns:35px minmax(0,1fr)!important;gap:2px 6px!important;min-height:70px!important;padding:8px 7px!important}.book .f-choice .f-vehicle-icon{width:34px;height:34px}.book .f-choice .f-vehicle-icon svg{width:28px!important;height:28px!important}.book .f-choice b{font-size:11px!important}.book .f-choice small{font-size:9px!important}}\n";
  const mobileHeaderAlignmentCSS = "\n/* Mobile header polish 2026-11-08: logo fully visible; CTAs aligned with the hero content edges. */\n@media(max-width:600px){\n .f-header .f-header-inner{box-sizing:border-box!important;padding:12px 16px 10px!important;grid-template-rows:minmax(94px,auto) auto!important;row-gap:4px!important;align-content:start!important}\n .f-header .f-logo-approved{height:94px!important;min-height:94px!important;align-items:center!important;overflow:visible!important;transform:translateY(3px)}\n .f-header .f-logo-approved img{display:block!important;width:100%!important;height:auto!important;max-height:none!important;object-fit:contain!important}\n .f-header .f-mobile-nav{align-self:center!important}\n .f-header .f-contact-actions{box-sizing:border-box!important;width:100%!important;max-width:100%!important;justify-self:stretch!important;gap:8px!important;margin:0!important;padding:5px 0 0!important;align-items:stretch!important}\n .f-header .f-contact-pill{box-sizing:border-box!important;width:100%!important;min-width:0!important;max-width:100%!important;height:44px!important;min-height:44px!important;gap:6px!important;padding:6px 7px!important;justify-content:center!important}\n .f-header .f-contact-pill strong{font-size:clamp(10px,3.25vw,12px)!important;white-space:nowrap!important}\n .f-header .f-contact-pill small{font-size:clamp(8px,2.45vw,10px)!important}\n}\n";
