  const cookieCSS="\n/* TD78_PRIVACY_CHOICES_20261109 — consent control, no tracking scripts installed */\n.td-cookie-panel[hidden],.td-cookie-details[hidden]{display:none!important}\n.td-cookie-panel{position:fixed;left:18px;bottom:18px;z-index:9000;width:min(540px,calc(100% - 36px));max-height:calc(100dvh - 36px);overflow:auto;padding:20px 22px 18px;background:#fff;color:#0b1f33;border:1px solid #cddfe4;border-radius:17px;box-shadow:0 15px 52px rgba(5,33,49,.28);font:inherit;line-height:1.5}\n.td-cookie-panel h2{font-size:21px!important;line-height:1.2!important;margin:0 32px 10px 0!important;color:#0b1f33!important}\n.td-cookie-panel p{font-size:13px!important;line-height:1.6!important;margin:0 0 12px!important;color:#355366!important}\n.td-cookie-panel a{font-size:13px!important;font-weight:800!important;color:#006c72!important;text-decoration:underline!important;text-underline-offset:2px}\n.td-cookie-close{position:absolute;right:14px;top:12px;border:0;background:#eef6f7;color:#193b4e;border-radius:9px;width:33px;height:33px;cursor:pointer;font-size:21px;line-height:1}\n.td-cookie-actions{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:14px}\n.td-cookie-actions button,.td-cookie-save,.td-cookie-policy-button{min-height:43px;border-radius:10px;padding:10px 13px;font:inherit;font-size:13px!important;font-weight:850!important;cursor:pointer}\n.td-cookie-reject,.td-cookie-accept{background:#087c82;color:#fff;border:2px solid #087c82;box-shadow:none}\n.td-cookie-reject:hover,.td-cookie-accept:hover{background:#065f67}\n.td-cookie-config{grid-column:1/-1;border:1px solid #bcd9da;color:#075e66;background:#fff}\n.td-cookie-config:hover,.td-cookie-policy-button:hover{background:#eaf7f6}\n.td-cookie-details{margin-top:13px;background:#f4f9f9;border:1px solid #d4e4e5;border-radius:12px;padding:13px}\n.td-cookie-details h3{font-size:14px!important;margin:0 0 8px!important}\n.td-cookie-details label{display:flex;align-items:flex-start;gap:9px;font-size:13px;font-weight:760;line-height:1.4;margin:10px 0}\n.td-cookie-details label small{font-size:11px;display:block;font-weight:450;color:#456075;margin-top:3px}\n.td-cookie-details input{accent-color:#087c82;width:18px;height:18px;margin:0;flex-shrink:0}\n.td-cookie-details input:disabled{opacity:1;accent-color:#087c82}\n.td-cookie-save,.td-cookie-policy-button{background:#087c82;color:#fff;border:0}\n.td-cookie-panel button:focus-visible,.td-cookie-reopen:focus-visible,.td-cookie-policy-button:focus-visible{outline:3px solid #d5a83f!important;outline-offset:3px}\n.td-cookie-reopen{appearance:none;background:none;border:0;padding:0;color:inherit;font:inherit;font-size:12px;cursor:pointer;text-decoration:underline;text-underline-offset:2px}\n.td-cookie-reopen:hover{text-decoration:none}\n@media(max-width:640px){.td-cookie-panel{bottom:0;left:0;width:100%;max-height:85dvh;border-radius:17px 17px 0 0;padding:18px 16px 17px}.td-cookie-panel h2{font-size:19px!important}.td-cookie-actions{gap:8px}.td-cookie-actions button{padding:9px 6px;font-size:12px!important}}\n@media(prefers-reduced-motion:reduce){.td-cookie-panel *{transition:none!important}}\n";
  function cookieConsentUi(){return "<aside class=\"td-cookie-panel\" id=\"td-cookie-panel\" role=\"region\" aria-labelledby=\"td-cookie-title\" hidden>\n<button type=\"button\" class=\"td-cookie-close\" data-td-cookie-action=\"reject\" aria-label=\"Fermer et refuser les cookies facultatifs\">×</button>\n<h2 id=\"td-cookie-title\">Votre vie privée compte</h2>\n<p>TaxiDirect utilise un cookie indispensable à la connexion des chauffeurs et administrateurs. <strong>Aucun cookie publicitaire ou statistique facultatif n'est actuellement activé.</strong> Vous pouvez mémoriser vos préférences.</p>\n<p><a href=\"/politique-cookies/\">Lire notre politique de cookies</a> · <a href=\"/confidentialite/\">Confidentialité</a></p>\n<div class=\"td-cookie-actions\"><button type=\"button\" class=\"td-cookie-reject\" data-td-cookie-action=\"reject\">Tout refuser</button><button type=\"button\" class=\"td-cookie-accept\" data-td-cookie-action=\"accept\">Tout accepter</button><button type=\"button\" class=\"td-cookie-config\" data-td-cookie-action=\"settings\" aria-expanded=\"false\" aria-controls=\"td-cookie-details\">Personnaliser mes choix</button></div>\n<div class=\"td-cookie-details\" id=\"td-cookie-details\" hidden><h3>Finalités des traceurs</h3>\n<label><input type=\"checkbox\" checked disabled aria-label=\"Cookies nécessaires toujours activés\"><span>Cookies nécessaires<small>Connexion sécurisée de l'espace professionnel, uniquement si vous vous connectez.</small></span></label>\n<label><input type=\"checkbox\" id=\"td-cookie-audience\"><span>Statistiques facultatives<small>Aucun outil n'est installé à ce jour. Ce choix n'active aucun traceur. Un nouvel accord sera demandé avant tout futur ajout.</small></span></label>\n<button type=\"button\" class=\"td-cookie-save\" data-td-cookie-action=\"save\">Enregistrer mes choix</button></div></aside><script>(function(){\n'use strict';\nvar panel=document.getElementById('td-cookie-panel');if(!panel)return;\nvar key='td78_consent_v1',version=1,ttl=183*24*60*60*1000;\nvar details=document.getElementById('td-cookie-details');\nvar audience=document.getElementById('td-cookie-audience');\nvar settings=panel.querySelector('[data-td-cookie-action=\"settings\"]');\nvar saved=null;\nfunction read(){try{var x=JSON.parse(localStorage.getItem(key)||'null');if(x&&x.version===version&&typeof x.at==='number'&&x.at<=Date.now()&&Date.now()-x.at<ttl&&typeof x.audience==='boolean'&&['accept','reject','custom'].indexOf(x.action)!==-1)return x;}catch(e){}return null}\nfunction store(on,action){var value={version:version,at:Date.now(),audience:!!on,action:action};try{localStorage.setItem(key,JSON.stringify(value))}catch(e){}saved=value;panel.hidden=true;details.hidden=true;settings.setAttribute('aria-expanded','false');try{window.dispatchEvent(new CustomEvent('td78:cookie-choice',{detail:{audience:value.audience,action:action}}))}catch(e){}}\nfunction open(){if(saved)audience.checked=saved.audience;details.hidden=true;settings.setAttribute('aria-expanded','false');panel.hidden=false;settings.focus();}\npanel.addEventListener('click',function(e){var b=e.target.closest('[data-td-cookie-action]');if(!b)return;var a=b.getAttribute('data-td-cookie-action');if(a==='reject')store(false,'reject');else if(a==='accept')store(true,'accept');else if(a==='save')store(audience.checked,'custom');else if(a==='settings'){details.hidden=!details.hidden;settings.setAttribute('aria-expanded',String(!details.hidden));if(!details.hidden)audience.focus();}});\ndocument.addEventListener('click',function(e){if(e.target.closest('[data-td-cookie-open]')){e.preventDefault();open();}});\npanel.addEventListener('keydown',function(e){if(e.key==='Escape'&&!panel.hidden)store(false,'reject');});\nsaved=read();window.td78CookiePreference=function(){return saved?{audience:saved.audience,action:saved.action}:null};\nif(!saved)panel.hidden=false;\n})();</script>";}
  const desktopMenuHoverCSS="\n/* DESKTOP_MENU_HOVER_REPAIR_20261109 — reliable mouse hover and seamless dropdowns */\n@media(min-width:1201px){\n .f-header,.f-header .f-header-inner,.f-header .f-nav{overflow:visible!important}\n .f-header .f-nav{position:relative!important;isolation:isolate}\n .f-header .f-nav>.nav-drop{position:relative!important;overflow:visible!important}\n .f-header .f-nav>.nav-drop>.nav-panel{top:calc(100% - 1px)!important;left:0!important;z-index:1000!important;min-width:240px!important;max-height:min(70vh,540px);overflow-y:auto;background:#fff!important}\n .f-header .f-nav>.nav-drop:hover>.nav-panel,.f-header .f-nav>.nav-drop.td-nav-open>.nav-panel,.f-header .f-nav>.nav-drop:focus-within>.nav-panel{display:flex!important;flex-direction:column!important}\n .f-header .f-nav>a:hover,.f-header .f-nav>a.td-nav-hover,.f-header .f-nav>a.nav-current:hover,\n .f-header .f-nav>.nav-drop>button:hover,.f-header .f-nav>.nav-drop>button.td-nav-hover,\n .f-header .f-nav>.nav-drop:hover>button,.f-header .f-nav>.nav-drop.td-nav-open>button,\n .f-header .f-nav>.nav-drop>button.nav-current:hover{\n   background:#078f91!important;background-image:linear-gradient(110deg,#087d85,#0cb4aa)!important;\n   color:#fff!important;border-color:#0a9895!important;box-shadow:0 5px 16px rgba(0,121,124,.18)!important\n }\n .f-header .f-nav .nav-panel>a:hover,.f-header .f-nav .nav-panel>a:focus-visible{\n   background:#078f91!important;background-image:linear-gradient(110deg,#087d85,#0cb4aa)!important;\n   color:#fff!important;border-left:3px solid #f1c95c!important\n }\n .f-header .f-nav>.nav-drop>button svg{color:inherit!important;stroke:currentColor!important}\n}\n@media(min-width:1201px) and (prefers-reduced-motion:reduce){.f-header .f-nav>a,.f-header .f-nav>.nav-drop>button{transition:none!important}}\n";
  function desktopMenuHoverJS(){return "<script>(function(){\n'use strict';\nvar mq=window.matchMedia('(min-width:1201px) and (hover:hover) and (pointer:fine)');\nvar groups=document.querySelectorAll('.f-header .f-nav>.nav-drop');\nfunction closeOthers(except){groups.forEach(function(group){if(group===except)return;group.classList.remove('td-nav-open');var b=group.querySelector(':scope>button');if(b)b.setAttribute('aria-expanded','false')})}\ngroups.forEach(function(group){var button=group.querySelector(':scope>button');if(!button)return;\ngroup.addEventListener('pointerenter',function(e){if(!mq.matches||e.pointerType!=='mouse')return;closeOthers(group);group.classList.add('td-nav-open');button.setAttribute('aria-expanded','true')});\ngroup.addEventListener('pointerleave',function(e){if(!mq.matches||e.pointerType!=='mouse')return;group.classList.remove('td-nav-open');button.setAttribute('aria-expanded','false')});\ngroup.addEventListener('focusout',function(e){if(!group.contains(e.relatedTarget)&&!group.matches(':hover')){group.classList.remove('td-nav-open');button.setAttribute('aria-expanded','false')}});\n});\ndocument.querySelectorAll('.f-header .f-nav>a').forEach(function(link){link.addEventListener('pointerenter',function(e){if(!mq.matches||e.pointerType!=='mouse')return;closeOthers(null);link.classList.add('td-nav-hover')});link.addEventListener('pointerleave',function(){link.classList.remove('td-nav-hover')})});\ndocument.addEventListener('keydown',function(e){if(e.key!=='Escape')return;closeOthers(null);if(document.activeElement&&document.activeElement.closest('.f-header .f-nav .nav-panel'))document.activeElement.blur()});\n})();</script>";}
